/**
 * Code Generator Templates & Transformation Specifications
 *
 * Contains all code generation templates and transformation specs.
 * Split from code-generator.js for maintainability (ADR-33 Phase 3).
 *
 * @module code-generator-templates
 */

'use strict';

/**
 * Code generation templates for Provider Pattern.
 * Generates complete, production-ready code.
 */
const PROVIDER_PATTERN_TEMPLATES = {
  registry: (options = {}) => `/**
 * Provider Registry – Auto-generated from ADR-${options.adrId || 'XXX'}
 *
 * Dynamic registration system for ${options.domain || 'providers'}.
 * Generated by WorkFlowAgent Code Generator.
 */

'use strict';

/**
 * Generic Provider Registry implementation.
 * Supports dynamic registration and lookup.
 */
class ProviderRegistry {
  constructor(options = {}) {
    this.providers = new Map();
    this.name = options.name || 'ProviderRegistry';
    this.strictMode = options.strictMode || false;
  }

  /**
   * Register a provider with the given key.
   *
   * @param {string} key – Unique identifier
   * @param {object} config – Provider configuration
   * @throws {Error} If key already exists in strict mode
   */
  register(key, config) {
    if (this.strictMode && this.providers.has(key)) {
      throw new Error(\`Provider '\${key}' already registered (strict mode)\`);
    }
    this.providers.set(key, config);
    return this;
  }

  /**
   * Get provider by key.
   *
   * @param {string} key
   * @returns {object|undefined}
   */
  get(key) {
    return this.providers.get(key);
  }

  /**
   * Check if provider exists.
   *
   * @param {string} key
   * @returns {boolean}
   */
  has(key) {
    return this.providers.has(key);
  }

  /**
   * Get all registered providers.
   *
   * @returns {IterableIterator<[string, object]>}
   */
  getAll() {
    return this.providers.entries();
  }

  /**
   * Get all provider keys.
   *
   * @returns {string[]}
   */
  keys() {
    return Array.from(this.providers.keys());
  }

  /**
   * Get provider count.
   *
   * @returns {number}
   */
  size() {
    return this.providers.size;
  }

  /**
   * Unregister a provider.
   *
   * @param {string} key
   * @returns {boolean} – Whether provider was removed
   */
  unregister(key) {
    return this.providers.delete(key);
  }

  /**
   * Clear all providers.
   */
  clear() {
    this.providers.clear();
  }

  /**
   * Load providers from JSON configuration.
   *
   * @param {string|object} config – Path to JSON file or config object
   */
  loadFromConfig(config) {
    const configs = typeof config === 'string'
      ? JSON.parse(require('fs').readFileSync(config, 'utf-8'))
      : config;

    Object.entries(configs).forEach(([key, providerConfig]) => {
      this.register(key, providerConfig);
    });

    return this;
  }

  /**
   * Create a readonly snapshot of current providers.
   *
   * @returns {Map}
   */
  snapshot() {
    return new Map(this.providers);
  }
}

module.exports = { ProviderRegistry };
`,

  ideProvider: (options = {}) => `/**
 * IDE Provider – Auto-generated from ADR-${options.adrId || 'XXX'}
 *
 * IDE detection provider with dynamic registration.
 * Replaces hardcoded IDE_SIGNATURES object.
 */

'use strict';

const { ProviderRegistry } = require('./provider-registry');
const path = require('path');
const fs = require('fs');

// Global IDE provider instance
const ideProvider = new ProviderRegistry({
  name: 'IDEProvider',
  strictMode: false,
});

/**
 * Default IDE configurations.
 * These are pre-registered for backward compatibility.
 */
const DEFAULT_IDE_CONFIGS = {
  vscode: {
    name: 'VS Code',
    envVars: ['VSCODE_PID', 'VSCODE_CWD'],
    identifiers: [
      { type: 'env', key: 'VSCODE_PID' },
    ],
  },
  cursor: {
    name: 'Cursor',
    envVars: ['CURSOR_TRACE_ID'],
    identifiers: [
      { type: 'env', key: 'CURSOR_TRACE_ID' },
    ],
  },
  windsurf: {
    name: 'Windsurf',
    envVars: ['WINDSURF_SESSION'],
    identifiers: [
      { type: 'env', key: 'WINDSURF_SESSION' },
    ],
  },
};

/**
 * Load IDE configurations from external file.
 *
 * @param {string} [configPath] – Path to config file (default: ./config/ides.json)
 * @returns {boolean} – Whether config was loaded
 */
function loadFromConfig(configPath) {
  const defaultPath = path.join(process.cwd(), 'config', 'ides.json');
  const targetPath = configPath || defaultPath;

  if (!fs.existsSync(targetPath)) {
    console.warn(\`[IDEProvider] Config not found: \${targetPath}\`);
    return false;
  }

  try {
    const configs = JSON.parse(fs.readFileSync(targetPath, 'utf-8'));
    Object.entries(configs).forEach(([key, config]) => {
      ideProvider.register(key, config);
    });
    console.log(\`[IDEProvider] Loaded \${Object.keys(configs).length} IDE configs from \${targetPath}\`);
    return true;
  } catch (err) {
    console.error(\`[IDEProvider] Failed to load config: \${err.message}\`);
    return false;
  }
}

/**
 * Auto-detect current IDE from environment.
 *
 * @returns {object|null} – Detected IDE config or null
 */
function detectCurrentIDE() {
  for (const [key, config] of ideProvider.getAll()) {
    if (config.envVars && config.envVars.some(env => process.env[env])) {
      return { key, ...config };
    }
  }
  return null;
}

/**
 * Check if running in specific IDE.
 *
 * @param {string} ideKey
 * @returns {boolean}
 */
function isIDE(ideKey) {
  const config = ideProvider.get(ideKey);
  if (!config || !config.envVars) return false;
  return config.envVars.some(env => process.env[env]);
}

/**
 * Get all supported IDE names.
 *
 * @returns {string[]}
 */
function getSupportedIDEs() {
  return Array.from(ideProvider.getAll()).map(([, config]) => config.name);
}

// Initialize with defaults
Object.entries(DEFAULT_IDE_CONFIGS).forEach(([key, config]) => {
  ideProvider.register(key, config);
});

// Try to load from config file
loadFromConfig();

module.exports = {
  ideProvider,
  loadFromConfig,
  detectCurrentIDE,
  isIDE,
  getSupportedIDEs,
  DEFAULT_IDE_CONFIGS,
};
`,

  config: (options = {}) => JSON.stringify({
    vscode: {
      name: 'VS Code',
      envVars: ['VSCODE_PID', 'VSCODE_CWD'],
      identifiers: [{ type: 'env', key: 'VSCODE_PID' }],
    },
    cursor: {
      name: 'Cursor',
      envVars: ['CURSOR_TRACE_ID'],
      identifiers: [{ type: 'env', key: 'CURSOR_TRACE_ID' }],
    },
    windsurf: {
      name: 'Windsurf',
      envVars: ['WINDSURF_SESSION'],
      identifiers: [{ type: 'env', key: 'WINDSURF_SESSION' }],
    },
    trae: {
      name: 'Trae',
      envVars: ['TRAE_SESSION'],
      identifiers: [{ type: 'env', key: 'TRAE_SESSION' }],
    },
    zed: {
      name: 'Zed',
      envVars: ['ZED_TERM'],
      identifiers: [{ type: 'env', key: 'ZED_TERM' }],
    },
  }, null, 2),
};

// ─── Transformation Specifications ──────────────────────────────────────────

// ─── Phase 4: Strategy Pattern Templates ────────────────────────────────────

/**
 * Strategy Pattern templates for SIMILAR_CONDITIONALS refactoring.
 */
const STRATEGY_PATTERN_TEMPLATES = {
  strategyMap: (options = {}) => `/**
 * Strategy Map – Auto-generated from ADR-${options.adrId || 'XXX'}
 *
 * Maps types to handler functions for dynamic dispatch.
 */

'use strict';

/**
 * Strategy registry for ${options.domain || 'operations'}.
 */
const ${options.mapName || 'strategyMap'} = new Map([
${(options.strategies || []).map(s => `  ['${s.type}', ${s.handler}],`).join('\n')}
]);

/**
 * Execute strategy for the given type.
 *
 * @param {string} type – Strategy type identifier
 * @param {...any} args – Arguments to pass to strategy
 * @returns {any} – Strategy result
 * @throws {Error} If strategy type not found
 */
function ${options.execName || 'executeStrategy'}(type, ...args) {
  const strategy = ${options.mapName || 'strategyMap'}.get(type);
  if (!strategy) {
    throw new Error(\`Unknown ${options.domain || 'type'}: \${type}\`);
  }
  return strategy(...args);
}

module.exports = {
  ${options.mapName || 'strategyMap'},
  ${options.execName || 'executeStrategy'},
};
`,

  strategyModule: (options = {}) => `/**
 * ${options.name || 'Strategy'} Module – Auto-generated
 */

'use strict';

/**
 * ${options.description || 'Strategy implementation'}
 *
 * @param {object} data – Input data
 * @returns {any} – Processed result
 */
function ${options.functionName || 'handleStrategy'}(data) {
${options.implementation || '  // TODO: Implement strategy logic\n  return data;'}
}

module.exports = { ${options.functionName || 'handleStrategy'} };
`,
};

// ─── Phase 4: Error Handler Templates ───────────────────────────────────────

/**
 * Centralized Error Handler templates.
 */
const ERROR_HANDLER_TEMPLATES = {
  handlerWrapper: (options = {}) => `/**
 * Error Handler Wrapper – Auto-generated from ADR-${options.adrId || 'XXX'}
 *
 * Centralized error handling for async functions.
 */

'use strict';

const logger = require('${options.loggerPath || '../utils/logger'}');

/**
 * Wrap a function with centralized error handling.
 *
 * @param {Function} fn – Function to wrap
 * @param {object} options – Handler options
 * @returns {Function} – Wrapped function
 */
function ${options.wrapperName || 'withErrorHandling'}(fn, options = {}) {
  const context = options.context || fn.name || 'anonymous';
  const rethrow = options.rethrow !== false;

  return async function(...args) {
    try {
      return await fn.apply(this, args);
    } catch (err) {
      // Log error
      console.error(\`[\${context}] Error: \${err.message}\`);
      logger.error(\`\${context} failed\`, { error: err.message, stack: err.stack });

      ${options.notifyHandler ? `
      // Notify if configured
      if (options.notify) {
        notifyError({ context, error: err.message });
      }
      ` : ''}

      // Metrics tracking
      if (global.metrics) {
        global.metrics.increment('error', { context });
      }

      ${options.rethrow !== false ? `
      if (rethrow) throw err;
      ` : '      // Error handled, no rethrow\n      return options.fallback;'}
    }
  };
}

/**
 * Wrap all methods of an object.
 *
 * @param {object} obj – Object whose methods to wrap
 * @param {object} options – Handler options
 * @returns {object} – New object with wrapped methods
 */
function ${options.wrapperName || 'withErrorHandling'}All(obj, options = {}) {
  const wrapped = {};
  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'function') {
      wrapped[key] = ${options.wrapperName || 'withErrorHandling'}(value, {
        ...options,
        context: options.context ? \`\${options.context}.\${key}\` : key,
      });
    } else {
      wrapped[key] = value;
    }
  }
  return wrapped;
}

module.exports = {
  ${options.wrapperName || 'withErrorHandling'},
  ${options.wrapperName || 'withErrorHandling'}All,
};
`,

  errorMiddleware: (options = {}) => `/**
 * Error Middleware – Auto-generated from ADR-${options.adrId || 'XXX'}
 *
 * Express/Connect-style error handling middleware.
 */

'use strict';

const logger = require('${options.loggerPath || '../utils/logger'}');

/**
 * Express error handling middleware.
 */
function errorMiddleware(err, req, res, next) {
  const errorId = generateErrorId();

  // Log error
  logger.error('Request error', {
    errorId,
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Send response
  const statusCode = err.statusCode || err.status || 500;
  res.status(statusCode).json({
    error: {
      id: errorId,
      message: process.env.NODE_ENV === 'production'
        ? 'Internal server error'
        : err.message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    },
  });
}

/**
 * Generate unique error ID.
 */
function generateErrorId() {
  return \`err_\${Date.now()}_\${Math.random().toString(36).substr(2, 9)}\`;
}

module.exports = { errorMiddleware };
`,
};

// ─── Transformation Specifications ──────────────────────────────────────────

/**
 * Transformation specifications define AST-based code changes.
 * Each spec includes:
 *   - match: Function to identify target code pattern
 *   - transform: Function to apply the transformation
 *   - validate: Function to verify semantic equivalence
 */
const TRANSFORMATION_SPECS = {
  EXTRACT_IDE_SIGNATURES: {
    id: 'EXTRACT_IDE_SIGNATURES',
    name: 'Extract hardcoded IDE_SIGNATURES to Provider',
    description: 'Transform hardcoded IDE detection to use ProviderRegistry',

    // Detect if file contains the pattern
    detect(sourceCode) {
      // Simple regex-based detection for pattern presence
      const pattern = /const\s+IDE_SIGNATURES\s*=\s*\{/;
      return pattern.test(sourceCode);
    },

    // Generate transformation preview
    preview(sourceCode, options = {}) {
      const preview = {
        original: sourceCode,
        transformed: null,
        changes: [],
        newFiles: [],
        warnings: [],
      };

      // Detect the hardcoded object
      const objectMatch = sourceCode.match(/const\s+IDE_SIGNATURES\s*=\s*\{[\s\S]*?\n\};/);
      if (!objectMatch) {
        preview.warnings.push('Could not locate IDE_SIGNATURES object');
        return preview;
      }

      // Extract entries for analysis
      const entries = [];
      const entryPattern = /(\w+):\s*\{[\s\S]*?name:\s*['"`]([^'"`]+)['"`][\s\S]*?\}/g;
      let match;
      while ((match = entryPattern.exec(objectMatch[0])) !== null) {
        entries.push({ key: match[1], name: match[2] });
      }

      preview.changes.push({
        type: 'replace',
        description: 'Replace IDE_SIGNATURES object with ideProvider import and usage',
        location: 'Object declaration',
        entriesFound: entries.length,
      });

      preview.newFiles.push(
        { path: 'workflow/core/provider-registry.js', purpose: 'Generic provider registry' },
        { path: 'workflow/core/ide-provider.js', purpose: 'IDE-specific provider' },
        { path: 'config/ides.json', purpose: 'External IDE configuration' }
      );

      preview.warnings.push('Manual review required: Update import statements in dependent files');

      return preview;
    },

    // Generate the actual transformation
    transform(sourceCode, options = {}) {
      const result = {
        success: false,
        transformed: null,
        changes: [],
        errors: [],
      };

      try {
        // Step 1: Replace object declaration with import
        let transformed = sourceCode.replace(
          /const\s+IDE_SIGNATURES\s*=\s*\{[\s\S]*?\n\};/,
          "const { ideProvider } = require('./ide-provider');"
        );

        // Step 2: Replace usages
        transformed = transformed.replace(
          /IDE_SIGNATURES\[(\w+)\]/g,
          'ideProvider.get($1)'
        );

        transformed = transformed.replace(
          /IDE_SIGNATURES\.(\w+)/g,
          'ideProvider.get("$1")'
        );

        transformed = transformed.replace(
          /Object\.keys\(IDE_SIGNATURES\)/g,
          'ideProvider.keys()'
        );

        transformed = transformed.replace(
          /Object\.entries\(IDE_SIGNATURES\)/g,
          'Array.from(ideProvider.getAll())'
        );

        result.transformed = transformed;
        result.success = true;
        result.changes.push(
          { type: 'import', description: 'Added ideProvider import' },
          { type: 'replace', description: 'Replaced IDE_SIGNATURES with ideProvider.get()' },
        );
      } catch (err) {
        result.errors.push(err.message);
      }

      return result;
    },
  },

  ADD_PROVIDER_IMPORT: {
    id: 'ADD_PROVIDER_IMPORT',
    name: 'Add provider import to existing file',
    description: 'Add import statement for ide-provider module',

    transform(sourceCode, options = {}) {
      const result = {
        success: false,
        transformed: null,
      };

      // Check if already has import
      if (sourceCode.includes("require('./ide-provider')")) {
        result.success = true;
        result.transformed = sourceCode;
        result.alreadyHasImport = true;
        return result;
      }

      // Add import at top of file
      const lines = sourceCode.split('\n');
      let insertIndex = 0;

      // Find last require statement
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].includes('require(')) {
          insertIndex = i + 1;
        }
      }

      lines.splice(insertIndex, 0, "const { ideProvider } = require('./ide-provider');");

      result.transformed = lines.join('\n');
      result.success = true;

      return result;
    },
  },

  EXTRACT_STRATEGY_PATTERN: {
    id: 'EXTRACT_STRATEGY_PATTERN',
    name: 'Extract Strategy Pattern from Conditionals',
    description: 'Convert similar if-else branches to Strategy Pattern with Map lookup',

    detect(sourceCode) {
      // Try AST detection first
      if (isASTEnabled() && astEngine?.transform?.detect) {
        const detections = astEngine.transform.detect(sourceCode);
        const strategy = detections.find(d => d.id === 'EXTRACT_STRATEGY_PATTERN');
        if (strategy) return { mode: 'ast', confidence: strategy.confidence };
      }

      // Fallback: regex detection
      const pattern = /if\s*\([^)]+\)\s*\{[^}]+\}\s*(?:else\s+if\s*\([^)]+\)\s*\{[^}]+\}){2,}/;
      return { mode: pattern.test(sourceCode) ? 'regex' : false, confidence: 0.6 };
    },

    preview(sourceCode, options = {}) {
      const detection = this.detect(sourceCode);

      if (!detection.mode) {
        return {
          applicable: false,
          reason: 'No applicable conditional pattern found',
        };
      }

      return {
        applicable: true,
        mode: detection.mode,
        confidence: detection.confidence,
        description: 'Convert if-else chain to Map-based Strategy Pattern',
        expectedChanges: [
          'Create strategy Map with type-function mappings',
          'Generate executeStrategy() lookup function',
          'Replace conditional chain with strategy lookup',
        ],
        benefits: [
          'Add new strategies without modifying existing code (OCP)',
          'Strategies are testable in isolation',
          'Eliminates duplicate conditional logic',
        ],
      };
    },

    transform(sourceCode, options = {}) {
      // Try AST transform first
      if (isASTEnabled() && astEngine?.transform?.apply) {
        const astResult = astEngine.transform.apply('EXTRACT_STRATEGY_PATTERN', sourceCode, options);
        if (astResult.success) {
          return { ...astResult, mode: 'ast' };
        }
      }

      // Fallback: regex-based transform
      const result = {
        success: false,
        transformed: null,
        changes: [],
        warnings: [],
        mode: 'regex',
      };

      try {
        // Simple regex transform as fallback
        let transformed = sourceCode;

        // Find type-dispatch pattern: if (x === 'a') ... else if (x === 'b') ...
        const typeMatch = sourceCode.match(/if\s*\(\s*(\w+)\s*===?\s*['"]([^'"]+)['"]\s*\)/);
        if (typeMatch) {
          const varName = typeMatch[1];

          transformed = transformed.replace(
            /(function\s+\w+\([^)]*\)\s*\{)[\s\S]*?(if\s*\([^)]+\)[\s\S]*?)(?:else\s*)?\}/,
            `$1\n  // Strategy Pattern: Auto-generated\n  const strategyMap = new Map([/* strategies */]);\n  const strategy = strategyMap.get(${varName});\n  if (!strategy) throw new Error(\`Unknown: \${${varName}}\`);\n  return strategy(args);\n}`
          );

          result.success = true;
          result.transformed = transformed;
          result.changes.push({
            type: 'extract_strategy',
            description: 'Converted conditionals to Strategy Pattern (regex fallback)',
          });
          result.warnings.push('AST engine recommended for complex transformations');
        }
      } catch (err) {
        result.errors = [err.message];
      }

      return result;
    },
  },

  CENTRALIZE_ERROR_HANDLING: {
    id: 'CENTRALIZE_ERROR_HANDLING',
    name: 'Centralize Error Handling',
    description: 'Extract duplicate error handling into reusable wrapper function',

    detect(sourceCode) {
      // Try AST detection first
      if (isASTEnabled() && astEngine?.transform?.detect) {
        const detections = astEngine.transform.detect(sourceCode);
        const handler = detections.find(d => d.id === 'CENTRALIZE_ERROR_HANDLING');
        if (handler) return { mode: 'ast', duplicates: handler.details?.duplicates };
      }

      // Fallback: count try-catch blocks
      const matches = sourceCode.match(/try\s*\{/g);
      const count = matches ? matches.length : 0;
      return { mode: count >= 3 ? 'regex' : false, count };
    },

    preview(sourceCode, options = {}) {
      const detection = this.detect(sourceCode);

      if (!detection.mode) {
        return {
          applicable: false,
          reason: 'Need 3+ try-catch blocks with similar handlers',
        };
      }

      return {
        applicable: true,
        mode: detection.mode,
        duplicateCount: detection.duplicates?.length || detection.count,
        description: 'Create reusable error handler wrapper function',
        expectedChanges: [
          'Generate withErrorHandling() wrapper function',
          'Replace try-catch blocks with wrapped calls',
          'Centralize error logging and notification',
        ],
        benefits: [
          'Single point of modification for error handling',
          'Consistent error processing across codebase',
          'Easier to add standardized error tracking',
        ],
      };
    },

    transform(sourceCode, options = {}) {
      // Try AST transform first
      if (isASTEnabled() && astEngine?.transform?.apply) {
        const astResult = astEngine.transform.apply('CENTRALIZE_ERROR_HANDLING', sourceCode, options);
        if (astResult.success) {
          return { ...astResult, mode: 'ast' };
        }
      }

      // Fallback: template-based generation
      const result = {
        success: false,
        transformed: null,
        changes: [],
        warnings: ['AST engine recommended for accurate detection'],
        mode: 'regex',
      };

      // Generate error handler template
      const handlerTemplate = `/**
 * Error Handler Wrapper – Auto-generated
 * Wraps async functions with centralized error handling.
 */
function withErrorHandling(fn, context = '') {
  return async function(...args) {
    try {
      return await fn.apply(this, args);
    } catch (err) {
      console.error(\`Error in \${context}:\`, err.message);
      // Add centralized logging here
      throw err;
    }
  };
}

`;

      // Prepend handler to source
      result.transformed = handlerTemplate + sourceCode;
      result.success = true;
      result.changes.push({
        type: 'add_error_handler',
        description: 'Added withErrorHandler() wrapper (manual application needed)',
      });

      return result;
    },
  },
};


// ─── Exports ────────────────────────────────────────────────────────────────

module.exports = {
  PROVIDER_PATTERN_TEMPLATES,
  STRATEGY_PATTERN_TEMPLATES,
  ERROR_HANDLER_TEMPLATES,
  TRANSFORMATION_SPECS,
};
